import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
/**
 * O "flair" do grupo no Discourse: um quadrado arredondado na cor do grupo
 * com o ícone dele. Sem ícone, a inicial do nome; sem cor, o cinza do tema.
 */
export default class GroupFlair extends Component {
  view() {
    const {
      group,
      size = 'normal'
    } = this.attrs;
    const color = group.color();
    const icon = group.icon();
    return m("span", {
      className: `CanelaGroupFlair CanelaGroupFlair--${size}${color ? ' CanelaGroupFlair--colored' : ''}`,
      style: color ? {
        '--group-color': color
      } : undefined,
      "aria-hidden": "true"
    }, icon ? m(Icon, {
      name: icon
    }) : m("span", {
      className: "CanelaGroupFlair-initial"
    }, (group.namePlural() || '?').charAt(0).toUpperCase()));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/community/GroupFlair', GroupFlair);