import app from 'flarum/forum/app';
import Avatar from 'flarum/common/components/Avatar';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LinkButton from 'flarum/common/components/LinkButton';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import ItemList from 'flarum/common/utils/ItemList';
import classList from 'flarum/common/utils/classList';
import { truncate } from 'flarum/common/utils/string';
import CommunityPage from './CommunityPage';
import DirectoryState from './DirectoryState';
import DirectoryTable from './DirectoryTable';
import DirectoryControls from './DirectoryControls';
import GroupFlair from './GroupFlair';
import { fetchGroupActivity } from './api';
import { findGroup, groupSlug, groupsEnabled, memberCount } from './groups';
import { forumBool, t } from '../../utils/settings';
import { fullDate, shortAge } from '../../utils/dates';
const EXCERPT_LENGTH = 300;

/**
 * A página de um grupo do Discourse (/g/:nome): o cabeçalho com o símbolo e o
 * nome, e as abas Membros e Atividade.
 *
 * A aba vai na própria URL (?tab=activity) pelo mesmo motivo do diretório:
 * trocar de aba não deve recriar a página e perder a lista carregada.
 */
export default class GroupPage extends CommunityPage {
  group = null;
  tab = 'members';
  members = null;
  posts = [];
  postsLoading = false;
  postsLoaded = false;
  postsPage = 0;
  postsHasMore = false;
  oninit(vnode) {
    // O grupo antes do `super`: o título da aba sai do nome dele.
    this.group = findGroup(m.route.param('name'));
    this.tab = m.route.param('tab') === 'activity' && this.activityEnabled() ? 'activity' : 'members';
    super.oninit(vnode);
    if (!this.enabled() || !this.group) return;
    if (this.canViewMembers()) {
      this.members = new DirectoryState({
        group: this.group.id(),
        order: 'username',
        dir: 'asc'
      });
      this.members.refresh();
    }
    if (this.tab === 'activity') this.loadActivity();
  }
  title() {
    return this.group ? this.group.namePlural() : t('community.groups.title');
  }
  className() {
    return 'CanelaGroupPage';
  }
  enabled() {
    return groupsEnabled();
  }
  activityEnabled() {
    return forumBool('canelaGroupsActivity', true);
  }
  canViewMembers() {
    return forumBool('canelaCanViewDirectory', false);
  }
  content() {
    if (!this.group) {
      return m("div", {
        className: "CanelaGroup"
      }, m("p", {
        className: "CanelaCommunity-empty"
      }, t('community.groups.not_found')), m(LinkButton, {
        className: "Button",
        href: app.route('canela.groups'),
        icon: "fas fa-arrow-left"
      }, t('community.groups.back')));
    }
    return m("div", {
      className: "CanelaGroup"
    }, this.header(this.group), this.tabs(), m("div", {
      className: "CanelaGroup-body"
    }, this.tab === 'activity' ? this.activity() : this.membersView()));
  }

  /** O `group-details-container`: o flair de 50px, o nome grande e o @endereço. */
  header(group) {
    return m("header", {
      className: "CanelaGroup-header",
      style: group.color() ? {
        '--group-color': group.color()
      } : undefined
    }, m("div", {
      className: "CanelaGroup-info"
    }, group.icon() && m(GroupFlair, {
      group: group,
      size: "large"
    }), m("div", {
      className: "CanelaGroup-headerInfo"
    }, m("h1", {
      className: "CanelaGroup-name"
    }, group.namePlural()), m("div", {
      className: "CanelaGroup-mention"
    }, "@", groupSlug(group)))));
  }
  tabs() {
    const items = new ItemList();
    const count = this.group ? memberCount(this.group) : null;
    items.add('members', this.tabButton('members', 'fas fa-users', t('community.groups.tab_members'), count), 100);
    if (this.activityEnabled()) {
      items.add('activity', this.tabButton('activity', 'fas fa-bars', t('community.groups.tab_activity')), 90);
    }
    return m("nav", {
      className: "CanelaGroup-tabs",
      "aria-label": t('community.groups.tabs_label')
    }, m("ul", null, items.toArray()));
  }
  tabButton(tab, icon, label, count = null) {
    const active = this.tab === tab;
    return m("li", {
      className: classList({
        active
      })
    }, m(Button, {
      className: classList('Button CanelaGroup-tab', {
        active
      }),
      icon: icon,
      "aria-current": active ? 'page' : undefined,
      onclick: () => this.setTab(tab)
    }, label, count !== null && m("span", {
      className: "CanelaGroup-tabCount"
    }, "(", count, ")")));
  }
  setTab(tab) {
    this.tab = tab;
    if (tab === 'activity' && !this.postsLoaded && !this.postsLoading) this.loadActivity();
    const url = app.route('canela.group', {
      name: m.route.param('name')
    }) + (tab === 'activity' ? '?tab=activity' : '');
    window.history.replaceState(window.history.state, '', url);
  }
  membersView() {
    if (!this.members) {
      return m("p", {
        className: "CanelaCommunity-empty"
      }, app.session.user ? t('community.groups.members_forbidden') : t('community.groups.members_login'));
    }
    return [m(DirectoryControls, {
      state: this.members
    }), m(DirectoryTable, {
      state: this.members,
      emptyText: t('community.groups.no_members')
    })];
  }
  loadActivity() {
    if (!this.group) return;
    this.postsLoading = true;
    const page = this.postsPage + 1;
    fetchGroupActivity(this.group.id(), page).then(response => {
      this.postsHasMore = response.meta.hasMore;
      this.postsPage = page;
      if (!response.data.length) return [];

      // Os ids já vêm filtrados pela visibilidade; o /api/posts serializa
      // cada postagem com o que as extensões acrescentam.
      return app.store.find('posts', {
        filter: {
          id: response.data.join(',')
        },
        include: 'user,discussion',
        page: {
          limit: response.data.length
        }
      });
    }).then(posts => {
      const sorted = [...posts].sort((a, b) => (b.createdAt()?.getTime() || 0) - (a.createdAt()?.getTime() || 0));
      this.posts = [...this.posts, ...sorted];
    }).catch(() => {}).finally(() => {
      this.postsLoading = false;
      this.postsLoaded = true;
      m.redraw();
    });
  }
  activity() {
    if (!this.postsLoaded && this.postsLoading) return m(LoadingIndicator, {
      display: "block"
    });
    if (!this.posts.length) return m("p", {
      className: "CanelaCommunity-empty"
    }, t('community.groups.no_activity'));
    return m("div", {
      className: "CanelaGroup-activity"
    }, m("ul", {
      className: "CanelaStream"
    }, this.posts.map(post => this.streamItem(post))), this.postsLoading && m(LoadingIndicator, {
      display: "block"
    }), !this.postsLoading && this.postsHasMore && m("div", {
      className: "CanelaCommunity-more"
    }, m(Button, {
      className: "Button",
      onclick: () => this.loadActivity()
    }, t('community.load_more'))));
  }

  /** Um item do "stream" de usuário do Discourse: avatar, tópico, quando e o começo do texto. */
  streamItem(post) {
    const user = post.user();
    const discussion = post.discussion();
    const createdAt = post.createdAt();
    return m("li", {
      key: post.id(),
      className: "CanelaStream-item"
    }, m("div", {
      className: "CanelaStream-header"
    }, user ? m(Link, {
      href: app.route.user(user),
      className: "CanelaStream-avatar"
    }, m(Avatar, {
      user: user
    })) : m("span", {
      className: "CanelaStream-avatar"
    }, m(Avatar, {
      user: null
    })), m("div", {
      className: "CanelaStream-titles"
    }, discussion && m(Link, {
      href: app.route.post(post),
      className: "CanelaStream-topic"
    }, discussion.title()), m("span", {
      className: "CanelaStream-meta"
    }, user && m(Link, {
      href: app.route.user(user)
    }, user.displayName()), createdAt && m("time", {
      datetime: createdAt.toISOString(),
      title: fullDate(createdAt)
    }, shortAge(createdAt))))), m("p", {
      className: "CanelaStream-excerpt"
    }, truncate(post.contentPlain() || '', EXCERPT_LENGTH)));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/community/GroupPage', GroupPage);